#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\DSH\src\dsh-src\node_modules\.pnpm\@yao-pkg+pkg@6.21.0_patch_h_6cfa04d6a14990fbb6788cbc5bff3130\node_modules\@yao-pkg\pkg\node_modules;D:\DSH\src\dsh-src\node_modules\.pnpm\@yao-pkg+pkg@6.21.0_patch_h_6cfa04d6a14990fbb6788cbc5bff3130\node_modules;D:\DSH\src\dsh-src\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/d/DSH/src/dsh-src/node_modules/.pnpm/@yao-pkg+pkg@6.21.0_patch_h_6cfa04d6a14990fbb6788cbc5bff3130/node_modules/@yao-pkg/pkg/node_modules:/proc/cygdrive/d/DSH/src/dsh-src/node_modules/.pnpm/@yao-pkg+pkg@6.21.0_patch_h_6cfa04d6a14990fbb6788cbc5bff3130/node_modules:/proc/cygdrive/d/DSH/src/dsh-src/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../@yao-pkg/pkg/lib-es5/bin.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../@yao-pkg/pkg/lib-es5/bin.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../@yao-pkg/pkg/lib-es5/bin.js" $args
  } else {
    & "node$exe"  "$basedir/../@yao-pkg/pkg/lib-es5/bin.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
